//! Compares the Rust references with the floats the Swift code dumped (`oracle/sq-render/effects/golden/effects.tsv`,
//! regenerated by `oracle/sq-render/effects/run.sh`). The cases here are the same list as `swift-dump/main.swift`.

use super::blend_modes;
use super::crop_mask;
use super::gaussian_blur;
use super::image_filters::{self as imf, Frame, Image};
use super::simd::{Float2, Float3, Float4};
use super::style_filters::{self, Family};
use super::ultra_key;
use super::visible_source_region::{self as vsr, SourceGeometry, SourceRegion};
use sq_core_effects::effects_evaluation::{ChromaKey, ChromaKeyOutput, CropInsets, ImageFilter};
use sq_core_masks::StabilizerEdgeFill;
use sq_core_model::{BlendMode, ClipTransform};
use sq_core_time::Vec2;
use std::collections::HashMap;

/// The Swift dump: key (tag and ids) to the printed floats.
struct Golden {
    rows: HashMap<String, Vec<f32>>,
    bad: Vec<String>,
    checked: usize,
}

impl Golden {
    fn load() -> Golden {
        let path =
            std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("../../oracle/sq-render/effects/golden/effects.tsv");
        let text = std::fs::read_to_string(path).unwrap_or_default();
        let mut rows = HashMap::new();
        for line in text.lines() {
            let (key, vals) = line.rsplit_once('\t').unwrap_or((line, ""));
            rows.insert(key.to_string(), vals.split_whitespace().filter_map(|v| v.parse().ok()).collect());
        }
        Golden { rows, bad: Vec::new(), checked: 0 }
    }

    /// Checks `got` against the row `key` within 1e-6 (relative above 1).
    fn check(&mut self, key: &str, got: &[f32]) {
        self.checked += 1;
        let Some(want) = self.rows.get(key) else {
            self.bad.push(format!("{key}: no golden row"));
            return;
        };
        if want.len() != got.len() {
            self.bad.push(format!("{key}: {} values, golden has {}", got.len(), want.len()));
            return;
        }
        for (i, (g, w)) in got.iter().zip(want).enumerate() {
            let same = (g.is_nan() && w.is_nan()) || g == w || (g - w).abs() <= 1e-6 * w.abs().max(1.0);
            if !same {
                self.bad.push(format!("{key}[{i}]: got {g}, golden {w}"));
                return;
            }
        }
    }

    fn check_image(&mut self, key: &str, img: &Image) {
        let flat: Vec<f32> = img.px.iter().flat_map(|p| [p.x, p.y, p.z, p.w]).collect();
        self.check(key, &flat);
    }

    fn check_ints(&mut self, key: &str, got: &[i64]) {
        let f: Vec<f32> = got.iter().map(|v| *v as f32).collect();
        self.check(key, &f);
    }
}

fn v4(p: Float4) -> [f32; 4] {
    [p.x, p.y, p.z, p.w]
}

fn colors() -> [Float4; 8] {
    [
        Float4::new(0.0, 0.0, 0.0, 0.0),
        Float4::new(0.25, 0.1, 0.05, 0.5),
        Float4::new(0.2, 0.3, 0.4, 1.0),
        Float4::new(0.9, 0.95, 0.1, 1.0),
        Float4::new(0.05, 0.1, 1.0, 1.0),
        Float4::new(0.4, 0.4, 0.4, 1.0),
        Float4::new(1.5, 0.2, 0.1, 0.8),
        Float4::new(0.6, 0.3, 0.7, 0.75),
    ]
}

fn test_pixel(x: usize, y: usize) -> Float4 {
    let a = if (x + y).is_multiple_of(5) { 0.6f32 } else { 1.0 };
    let r = ((x * 7 + y * 13) % 17) as f32 / 17.0;
    let g = ((x * 5 + y * 3) % 11) as f32 / 11.0;
    let b = ((x * 3 + y * 11) % 13) as f32 / 13.0;
    Float4::new(r * a, g * a, b * a, a)
}

fn test_image() -> Image {
    Image::from_fn(16, 12, test_pixel)
}

fn test_frame() -> Frame {
    Frame { center: Float2::new(8.0, 6.0), size: Float2::new(12.0, 8.0) }
}

fn blend_cases(g: &mut Golden) {
    let cols = colors();
    for m in BlendMode::ALL {
        let id = blend_modes::shader_id(m);
        for (si, s) in cols.iter().enumerate() {
            for (di, d) in cols.iter().enumerate() {
                g.check(&format!("blend\t{id}\t{si}\t{di}"), &v4(blend_modes::blend(m, *s, *d, 3, 5)));
            }
        }
    }
    let pts = [(0, 0), (1, 0), (0, 1), (7, 9), (-3, 4), (100, -200), (4095, 4095)];
    let dis: Vec<f32> = pts.iter().map(|(x, y)| blend_modes::dissolve_threshold(*x, *y)).collect();
    g.check("dissolve", &dis);
}

fn crop_cases(g: &mut Golden) {
    let size = Float2::new(50.0, 30.0);
    let crops = [
        (CropInsets::NONE, 8.0f32, false, 0.0f32),
        (CropInsets { left: 0.1, top: 0.05, right: 0.2, bottom: 0.0 }, 8.0, false, 0.0),
        (CropInsets { left: 0.1, top: 0.05, right: 0.2, bottom: 0.0 }, 8.0, true, 3.0),
        (CropInsets { left: 0.3, top: 0.3, right: 0.1, bottom: 0.1 }, 100.0, false, 2.0),
    ];
    for (ci, c) in crops.iter().enumerate() {
        let mut vals = Vec::new();
        for j in 0..5 {
            for i in 0..7 {
                let p = Float2::new(i as f32 * 8.0 - 24.5, j as f32 * 7.0 - 14.5);
                vals.push(crop_mask::signed_distance(p, size, &c.0, c.1, c.2));
                vals.push(crop_mask::coverage(p, size, &c.0, c.1, c.2, c.3));
            }
        }
        g.check(&format!("crop\t{ci}"), &vals);
    }
}

fn key_cases(g: &mut Golden) {
    let green = ChromaKey::new(120.0, 36.0, 13.0, 0.5, 0.0, 0.0);
    let mut shaped = green;
    shaped.choke = 0.3;
    shaped.pedestal = 0.1;
    let mut rich = ChromaKey::new(200.0, 20.0, 25.0, 0.8, -0.4, 0.05);
    rich.contrast = 0.5;
    rich.midpoint = 0.4;
    rich.keep_highlights = 0.5;
    rich.keep_shadows = 0.3;
    rich.spill_range = 0.8;
    rich.saturation = 1.2;
    rich.hue_shift = 20.0;
    rich.luma = 0.9;
    let luma = ChromaKey::luma_key(0.4, 0.2, false);
    let mut luma_brights = ChromaKey::luma_key(0.4, 0.2, true);
    luma_brights.contrast = 0.5;
    luma_brights.choke = 0.2;
    let mut matte = green;
    matte.output = ChromaKeyOutput::Alpha;
    let mut source = green;
    source.output = ChromaKeyOutput::Source;
    let sets: [Vec<ChromaKey>; 8] = [
        vec![green],
        vec![shaped],
        vec![rich],
        vec![luma],
        vec![luma_brights],
        vec![matte],
        vec![source, green],
        vec![green, rich, shaped],
    ];
    let colors = [
        Float3::new(0.05, 0.6, 0.05),
        Float3::new(0.7, 0.1, 0.1),
        Float3::new(0.4, 0.4, 0.4),
        Float3::new(0.0, 0.0, 0.0),
        Float3::new(0.1, 0.5, 0.367),
        Float3::new(0.5, 0.45, 0.1),
        Float3::new(0.1, 0.4, 0.8),
        Float3::new(0.9, 0.95, 0.85),
        Float3::new(0.02, 0.05, 0.01),
        Float3::new(1.2, 0.3, 0.2),
    ];
    for (ki, keys) in sets.iter().enumerate() {
        for (ci, c) in colors.iter().enumerate() {
            let (rgb, a) = ultra_key::apply(*c, 0.9, keys);
            g.check(&format!("key\t{ki}\t{ci}"), &[rgb.x, rgb.y, rgb.z, a]);
        }
    }
    for (ci, c) in colors.iter().enumerate() {
        let (h, s, v) = ultra_key::hsv(*c);
        g.check(&format!("hsv\t{ci}"), &[h, s, v]);
    }
    for (ki, k) in [green, shaped, rich, luma_brights].iter().enumerate() {
        let mut all = Vec::new();
        for v in
            [ultra_key::matte_vector(k), ultra_key::shape_vector(k), ultra_key::color_vector(k), ultra_key::vector(k)]
        {
            all.extend(v4(v));
        }
        g.check(&format!("keyvec\t{ki}"), &all);
    }
}

fn blur_cases(g: &mut Golden) {
    for (i, s) in [0.5f32, 1.7, 3.0].iter().enumerate() {
        g.check(&format!("weights\t{i}"), &gaussian_blur::weights(*s, None));
    }
    type PlanCase = (f64, f64, f64, f64, Option<f64>, i64, i64);
    let plans: [PlanCase; 7] = [
        (100.0, 50.0, 4.0, 0.0, None, 1, i64::MAX),
        (1000.0, 1000.0, 30.0, 0.0, None, 1, i64::MAX),
        (100.0, 50.0, 1.0, 0.0, None, 2, i64::MAX),
        (100.0, 50.0, 0.0, 0.0, None, 1, i64::MAX),
        (1000.0, 1000.0, 2.0, 500.0, None, 1, 1_500_000),
        (1920.0, 1080.0, 9.0, 40.0, Some(12.0), 1, i64::MAX),
        (20000.0, 100.0, 3.0, 0.0, None, 1, i64::MAX),
    ];
    for (i, p) in plans.iter().enumerate() {
        let pl = gaussian_blur::Plan::new(p.0, p.1, p.2, p.3, p.4, p.5, p.6);
        g.check(
            &format!("gplan\t{i}"),
            &[
                pl.factor as f32,
                pl.sigma,
                pl.radius as f32,
                pl.texture_width as f32,
                pl.texture_height as f32,
                pl.content_width,
                pl.content_height,
                pl.output_width(),
                pl.output_height(),
            ],
        );
    }
    let img = test_image();
    let blurred =
        |sigma, edges| Image { width: 16, height: 12, px: gaussian_blur::blur(&img.px, 16, 12, sigma, edges) };
    g.check_image("blur\t0", &blurred(1.7, false));
    g.check_image("blur\t1", &blurred(2.4, true));
}

fn image_filter_cases(g: &mut Golden) {
    let img = test_image();
    let frame = test_frame();
    for (i, d) in [Float2::new(7.0, 3.0), Float2::new(0.0, 8.0), Float2::new(40.0, 20.0), Float2::new(0.0, 0.0)]
        .iter()
        .enumerate()
    {
        let n = imf::smear_taps(*d);
        let p = imf::smear_passes(n);
        g.check_ints(&format!("smear\t{i}"), &[n, p.map_or(-1, |p| p.0), p.map_or(-1, |p| p.1)]);
    }
    let r = imf::pixel_rect(frame.origin(), frame.size, 16, 12);
    let small = Frame { center: Float2::new(0.0, 0.0), size: Float2::new(7.5, 9.0) };
    let q = imf::pixel_rect(small.origin(), small.size, 16, 12);
    g.check_ints("pixelrect", &[r.0, r.1, r.2, r.3, q.0, q.1, q.2, q.3]);
    g.check_image("sharpen\t0", &imf::sharpen(&img, 1.5, None));
    g.check_image("sharpen\t1", &imf::sharpen(&img, 1.5, Some(frame)));
    g.check_image("unsharp\t0", &imf::unsharp_mask(&img, 2.0, 1.2, 0.05, Some(frame)));
    g.check_image("unsharp\t1", &imf::unsharp_mask(&img, 9.0, 0.7, 0.0, None));
    g.check_image("dirblur\t0", &imf::directional_blur(&img, Float2::new(7.0, 3.0)));
    g.check_image("dirblur\t1", &imf::directional_blur(&img, Float2::new(40.0, 20.0)));
    g.check_image("mirror\t0", &imf::mirror(&img, Float2::new(10.0, 9.0), 33.0));
    g.check_image("mirror\t1", &imf::mirror(&img, Float2::new(8.0, 6.0), 90.0));
    g.check_image("noise\t0", &imf::noise(&img, 0.3, true, true, 7));
    g.check_image("noise\t1", &imf::noise(&img, 0.5, false, false, 99));
    g.check_image("glow\t0", &imf::glow(&img, 0.4, 2.5, 0.8, None));
    g.check_image("glow\t1", &imf::glow(&img, 0.2, 1.5, 1.3, Some(Float3::new(0.9, 0.4, 0.2))));
    for (i, m) in [(4, 3, false), (5, 4, true), (3, 3, false), (16, 12, false), (30, 20, false)].iter().enumerate() {
        g.check_image(&format!("mosaic\t{i}"), &imf::mosaic(&img, &frame, m.0, m.1, m.2));
    }
    g.check("hash01", &[imf::hash01(0, 0, 0, 0), imf::hash01(5, 9, 7, 2), imf::hash01(4_000_000_000, 123_456, 99, 1)]);
}

