fn style_cases(g: &mut Golden) {
    let img = test_image();
    let frame = test_frame();
    for (i, (name, f)) in style_list().iter().enumerate() {
        let Some((fam, u)) = style_filters::plan(f, &frame, 1.5) else {
            g.check(&format!("style\t{i}\tnone"), &[]);
            continue;
        };
        let fam_id = match fam {
            Family::Pixel => 0.0,
            Family::Warp => 1.0,
            Family::RgbSplit => 2.0,
            Family::RadialBlur => 3.0,
            Family::Lens => 4.0,
            Family::Glitch => 5.0,
        };
        let mut vals = vec![fam_id];
        for v in [u.a, u.b] {
            vals.extend(v4(v));
        }
        vals.extend([u.center.x, u.center.y, u.frame.x, u.frame.y]);
        vals.extend([u.i.x as f32, u.i.y as f32, u.i.z as f32, u.i.w as f32]);
        for v in [u.c, u.d] {
            vals.extend(v4(v));
        }
        g.check(&format!("plan\t{i}\t{name}"), &vals);
        if let Some(r) = style_filters::reference(f, &img, &frame, 1.5) {
            g.check_image(&format!("style\t{i}\t{name}"), &r);
        }
    }
    let h = style_filters::homography(
        &[[0.0, 0.0], [1.0, 0.0], [1.0, 1.0], [0.0, 1.0]],
        &[[0.1, 0.2], [1.2, 0.0], [0.9, 1.1], [0.0, 0.8]],
    );
    let h: Vec<f32> = h.map(|h| h.iter().map(|v| *v as f32).collect()).unwrap_or_default();
    g.check("homography", &h);
}

fn geometry_cases(g: &mut Golden) {
    let mk = |canvas: (f32, f32),
              pos: Vec2,
              scale: f64,
              rot: f64,
              size: (f32, f32),
              tex: (i64, i64),
              quarter: u32,
              tilt: f64,
              anchor: Vec2| {
        let mut t = ClipTransform::IDENTITY;
        t.position = pos;
        t.scale = Vec2::new(scale, scale);
        t.rotation = rot;
        t.anchor = anchor;
        t.tilt_x = tilt;
        SourceGeometry {
            canvas: Float2::new(canvas.0, canvas.1),
            transform: t,
            size: Float2::new(size.0, size.1),
            texture: tex,
            quarter,
        }
    };
    let z = Vec2::ZERO;
    let cases = [
        mk((1080.0, 1920.0), z, 1.0, 0.0, (3840.0, 2160.0), (3840, 2160), 0, 0.0, z),
        mk((1080.0, 1920.0), Vec2::new(100.0, 0.0), 2.0, 0.0, (3840.0, 2160.0), (3840, 2160), 0, 0.0, z),
        mk((1080.0, 1920.0), z, 1.0, 90.0, (3840.0, 2160.0), (3840, 2160), 0, 0.0, z),
        mk((1080.0, 1920.0), z, 1.0, 0.0, (3840.0, 2160.0), (2160, 3840), 1, 0.0, z),
        mk(
            (1080.0, 1920.0),
            Vec2::new(-37.0, 12.0),
            0.7,
            33.0,
            (3840.0, 2160.0),
            (3840, 2160),
            2,
            0.0,
            Vec2::new(20.0, -10.0),
        ),
        mk((1080.0, 1920.0), Vec2::new(5.0, 5.0), 0.5, 17.0, (3840.0, 2160.0), (2160, 3840), 3, 0.0, z),
        mk((100.0, 100.0), Vec2::new(5000.0, 0.0), 1.0, 0.0, (200.0, 200.0), (200, 200), 0, 0.0, z),
        mk((100.0, 100.0), z, 1.0, 0.0, (200.0, 200.0), (200, 100), 0, 10.0, z),
        mk((640.0, 360.0), z, 0.5, 0.0, (1280.0, 720.0), (1280, 720), 0, 0.0, z),
    ];
    let region = |r: Option<SourceRegion>| r.map_or(vec![0], |r| vec![1, r.x, r.y, r.width, r.height]);
    for (i, c) in cases.iter().enumerate() {
        for (pad, cp) in [(0i64, 0.0f32), (4, 0.0), (2, 2.0)] {
            g.check_ints(
                &format!("region\t{i}\t{pad}\t{}", cp as i64),
                &region(vsr::visible_source_region(c, pad, cp)),
            );
        }
        for (tpn2, one_pass, strong, halves) in
            [(2, true, false, true), (1, true, false, true), (2, false, true, true), (2, true, false, false)]
        {
            let w = vsr::color_work(c, tpn2 as f32 / 2.0, one_pass, strong, halves);
            let mut vals = vec![w.width, w.height];
            vals.extend(region(w.region));
            g.check_ints(
                &format!("colorwork\t{i}\t{tpn2}\t{}\t{}\t{}", one_pass as i32, strong as i32, halves as i32),
                &vals,
            );
        }
        let d = vsr::display_color_work(c, 1.0, true);
        let vals = d.map_or(vec![0], |d| {
            let mut v = vec![1, d.width, d.height];
            v.extend(region(d.region));
            v
        });
        g.check_ints(&format!("display\t{i}"), &vals);
        g.check_ints(&format!("effectfactor\t{i}"), &[vsr::effect_work_factor(&c.transform, c.size)]);
    }
}

#[test]
fn rust_references_match_the_swift_dump() {
    let mut g = Golden::load();
    assert!(g.rows.len() > 1000, "golden file missing: run oracle/sq-render/effects/run.sh");
    blend_cases(&mut g);
    crop_cases(&mut g);
    key_cases(&mut g);
    blur_cases(&mut g);
    image_filter_cases(&mut g);
    style_cases(&mut g);
    geometry_cases(&mut g);
    assert_eq!(g.checked, g.rows.len(), "every golden row has a Rust case");
    assert!(
        g.bad.is_empty(),
        "{} of {} rows differ, first: {:#?}",
        g.bad.len(),
        g.checked,
        &g.bad[..g.bad.len().min(25)]
    );
}
